        return '<p class="mb-assignment-file"><strong>Assignment file:</strong> <a target="_blank" rel="noopener" href="'.esc_url(self::assignment_file_url($student_id,$note_id,$version)).'">'.esc_html($source['attachment']['name']).'</a></p>';
