    private static function attachment_preview(array $source,$student_id,$note_id,$version=0) {
        $attachment=(array)($source['attachment']??[]);if(empty($attachment['name']))return '';$url=self::assignment_file_url($student_id,$note_id,$version);$type=sanitize_mime_type($attachment['type']??'');
        if(strpos($type,'image/')===0)return '<img class="mb-assignment-upload-preview" src="'.esc_url($url).'" alt="'.esc_attr($attachment['name']).'">';
        if($type==='application/pdf')return '<iframe class="mb-assignment-pdf-preview" src="'.esc_url($url).'#toolbar=1" title="'.esc_attr($attachment['name']).'"></iframe>';
        return '';
    }

