        if($query!=='')$notes=array_filter($notes,function($note)use($query){return stripos(($note['title']??'').' '.($note['organization_label']??''),$query)!==false;});
        $groups=[];foreach($notes as $note){$key=$note['organization_label']??'Other';$groups[$key][]=$note;}
        ob_start(); ?>
