        <form class="mb-work-library-filters" method="get"><label>Find work<input type="search" name="work_search" value="<?php echo esc_attr($query); ?>" placeholder="Search titles or topics"></label><label>Status<select name="status"><?php foreach(['all'=>'All work','draft'=>'Drafts','revision_requested'=>'Revisions','submitted'=>'Submitted','feedback'=>'Feedback','graded'=>'Graded'] as $key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($status,$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><button type="submit">Filter</button></form>
        <?php if(!$notes): ?><div class="mb-dashboard-empty"><strong>No work matches this view.</strong><p>Create a note or assignment workspace, or change the filter.</p></div><?php else: foreach($groups as $group=>$items): ?><section class="mb-work-group"><div class="mb-work-group-heading"><h2><?php echo esc_html($group); ?></h2><span><?php echo count($items); ?> item<?php echo count($items)===1?'':'s'; ?></span></div><div class="mb-work-card-grid"><?php foreach($items as $note): $preview=trim(wp_strip_all_tags($note['content']??'')); ?><article class="mb-work-card is-<?php echo esc_attr($note['color']??'teal'); ?>"><span class="mb-work-status is-<?php echo esc_attr($note['status']??'draft'); ?>"><?php echo esc_html(self::status_label($note['status']??'draft')); ?></span><h3><?php echo esc_html($note['title']); ?></h3><p><?php echo esc_html($preview!==''?mb_substr($preview,0,115):(!empty($note['attachment']['name'])?'File: '.$note['attachment']['name']:'Drawing saved')); ?></p><small>Version <?php echo absint($note['version']??0); ?> · Updated <?php echo esc_html(wp_date(get_option('date_format'),strtotime($note['updated_at']??$note['created_at']??'now'))); ?></small><a href="<?php echo esc_url(self::workspace_url(['work'=>$note['id']])); ?>">Open Work <span aria-hidden="true">→</span></a></article><?php endforeach; ?></div></section><?php endforeach; endif; ?>
        <?php return ob_get_clean();
    }

