        <?php if($is_new): ?><p class="mb-workspace-class-help"><strong>Create work and select a class:</strong> add a title, choose the class in the form, then write, draw, or upload a PDF or image. Choose “Private / not assigned” when the work is only for you.</p><?php endif; ?>
        <?php if(!$is_new&&!empty($note['review']['feedback'])): ?><div class="mb-note-notice <?php echo ($note['status']??'')==='revision_requested'?'is-error':'is-success'; ?>"><strong>Teacher feedback</strong><?php echo wp_kses_post(wpautop($note['review']['feedback'])); ?><?php if(($note['status']??'')==='graded'): ?><p><strong>Grade:</strong> <?php echo esc_html((string)($note['review']['score']??0)); ?><?php echo !empty($note['review']['points_possible'])?' / '.esc_html((string)$note['review']['points_possible']):''; ?></p><?php endif; ?></div><?php endif; ?>
        <?php if($editable): ?><section class="mb-work-editor-panel"><?php echo self::editor($note,$classes); ?></section><?php if(!$is_new): ?><div class="mb-work-actions"><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" onsubmit="return confirm('Submit this exact version to your teacher?');"><input type="hidden" name="action" value="mb_student_submit_math_note"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_student_submit_math_note','mb_math_note_submit_nonce'); ?><button class="mb-button mb-button-primary" type="submit"><?php echo ($note['status']??'')==='revision_requested'?'Submit Revised Version':'Submit to Teacher'; ?></button></form></div><?php endif; ?>
        <?php else: ?><article class="mb-work-submitted"><p>This submitted version is locked. A teacher can return it for revision.</p><?php echo self::attachment_link($source,$student_id,$note['id'],absint($source['version']??0)); ?><?php if(!empty($source['content'])): ?><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($source['content'])); ?></div><?php endif; ?><?php if(!empty($source['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($source['drawing_data']); ?>" alt="Submitted drawing"><?php endif; ?></article><?php endif; ?>
        <?php return ob_get_clean();
    }

