        $student_id=get_current_user_id();$notes=array_reverse(array_filter(self::all($student_id),function($note){return empty($note['student_deleted']);}),true);$classes=self::classes($student_id);$notice=sanitize_key(wp_unslash($_GET['notes_notice']??''));
