        $student_id=get_current_user_id(); $notes=array_reverse(array_filter(self::all($student_id),function($note){return empty($note['student_deleted']);})); $classes=self::classes($student_id); $notice=sanitize_key(wp_unslash($_GET['notes_notice']??'')); $messages=['saved'=>'Private draft saved.','submitted'=>'A locked snapshot was submitted to your teacher.','deleted'=>'The note was removed from My Math Notes. Any previously submitted snapshot remains in your class evidence history.','delete_invalid'=>'That note could not be found.','invalid'=>'Add a title, organization label, and notes, a drawing, or an assignment file.','locked'=>'That submitted version is locked.','submit_invalid'=>'Choose an active class before submitting.','file_invalid'=>'Choose a JPG, PNG, WebP, or PDF file no larger than 8 MB.','file_storage'=>'Your file could not be stored. Please try again or ask an administrator for help.']; ob_start(); ?>
        <?php $attachments=array_filter($notes,function($note){return !empty($note['attachment']['name']);}); if($attachments): ?><section class="mb-panel mb-student-assignment-files"><div class="mb-panel-heading"><div><span class="mb-eyebrow">Private assignment workspace</span><h2>My Uploaded Assignments</h2></div><strong><?php echo count($attachments); ?></strong></div><p>Uploaded files stay private until you submit that work to a teacher.</p><?php foreach($attachments as $uploaded_note): ?><p class="mb-assignment-file"><a target="_blank" rel="noopener" href="<?php echo esc_url(self::assignment_file_url($student_id,$uploaded_note['id'])); ?>"><?php echo esc_html($uploaded_note['attachment']['name']); ?></a> · <?php echo esc_html($uploaded_note['title']); ?></p><?php endforeach; ?></section><?php endif; ?>
        <section id="my-math-notes" class="mb-panel mb-math-notes"><div class="mb-panel-heading"><div><span class="mb-eyebrow">Student-controlled work</span><h2>My Math Notes</h2></div><strong><?php echo count($notes); ?></strong></div><p class="mb-note-privacy"><strong>Private by default.</strong> Teachers see only the version you deliberately submit. A submitted snapshot does not change when you edit later.</p><?php if($notice): ?><div class="mb-note-notice is-<?php echo in_array($notice,['invalid','locked','submit_invalid'],true)?'error':'success'; ?>"><?php echo esc_html($messages[$notice]??'Math notes updated.'); ?></div><?php endif; ?><details class="mb-note-create" <?php echo !$notes?'open':''; ?>><summary>Create a math note</summary><?php echo self::editor([],$classes); ?></details>
        <?php if(!$notes): ?><div class="mb-dashboard-empty"><strong>No structured notes yet.</strong><p>Create private notes organized by topic, unit, standard, I Can statement, week, vocabulary, or your own category.</p></div><?php else: ?><div class="mb-note-list"><?php foreach($notes as $note): $editable=in_array($note['status']??'draft',['draft','revision_requested'],true); ?><article class="mb-note-card is-<?php echo esc_attr($note['color']??'teal'); ?>"><small><?php echo esc_html(ucwords(str_replace('_',' ',$note['status']??'draft'))); ?> · Version <?php echo absint($note['version']??0); ?></small><h3><?php echo esc_html($note['title']); ?></h3><p><strong><?php echo esc_html(ucfirst($note['organization_type'])); ?>:</strong> <?php echo esc_html($note['organization_label']); ?><?php if(!empty($note['subcategory_label'])): ?> → <strong><?php echo esc_html($note['subcategory_type']?:'Subcategory'); ?>:</strong> <?php echo esc_html($note['subcategory_label']); ?><?php endif; ?></p><?php if(!empty($note['content'])): ?><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($note['content'])); ?></div><?php endif; ?><?php if(!empty($note['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($note['drawing_data']); ?>" alt="Saved math drawing"><?php endif; ?><?php if(!empty($note['review']['feedback'])): ?><blockquote><strong>Teacher feedback</strong><?php echo wp_kses_post(wpautop($note['review']['feedback'])); ?><?php if(($note['status']??'')==='graded'): ?><p><strong>Grade:</strong> <?php echo esc_html((string)($note['review']['score']??0)); ?><?php echo !empty($note['review']['points_possible'])?' / '.esc_html((string)$note['review']['points_possible']):''; ?> (<?php echo esc_html(ucfirst($note['review']['grade_type']??'points')); ?>)</p><?php endif; ?></blockquote><?php endif; ?><?php if($editable): ?><details><summary>Edit private working copy</summary><?php echo self::editor($note,$classes); ?></details><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" onsubmit="return confirm('Submit this exact version to your teacher? The submitted snapshot will be locked.');"><input type="hidden" name="action" value="mb_student_submit_math_note"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_student_submit_math_note','mb_math_note_submit_nonce'); ?><button type="submit">Submit this version to Teacher</button></form><?php else: ?><p>This submitted snapshot is locked.<?php echo ($note['status']??'')==='graded'?' Your teacher has graded it.':''; ?></p><?php endif; ?><form class="mb-note-delete-form" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" onsubmit="return confirm('Delete this note from My Math Notes? Previously submitted snapshots will stay in class evidence history.');"><input type="hidden" name="action" value="mb_student_delete_math_note"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_student_delete_math_note','mb_math_note_delete_nonce'); ?><button class="mb-note-delete" type="submit">Delete Note</button></form></article><?php endforeach; ?></div><?php endif; ?></section><?php return ob_get_clean();
    }
    private static function teacher_review_rows($teacher_id,array $classes) {
        global $wpdb;$rows=[];
        foreach($classes as $class){
            $class_id=absint($class['id']??0);if(!$class_id||!MathBinder_Class_Staff::can($teacher_id,$class_id,'view_evidence'))continue;
            $students=$wpdb->get_results($wpdb->prepare("SELECT u.ID,u.display_name,u.user_email FROM {$wpdb->prefix}mb_enrollments e JOIN {$wpdb->users} u ON u.ID=e.user_id WHERE e.class_id=%d AND e.role_key='student' AND e.status='active' ORDER BY u.display_name",$class_id),ARRAY_A)?:[];
            foreach($students as $student){foreach(self::submitted_for_student($student['ID'],[$class_id]) as $note){$rows[]=['student_id'=>absint($student['ID']),'student_name'=>$student['display_name']?:$student['user_email'],'student_email'=>$student['user_email'],'class_id'=>$class_id,'class_name'=>$class['name'].(!empty($class['section_name'])?' · '.$class['section_name']:''),'note'=>$note];}}
        }
        usort($rows,function($a,$b){$at=strtotime($a['note']['submitted_snapshot']['submitted_at']??$a['note']['updated_at']??'');$bt=strtotime($b['note']['submitted_snapshot']['submitted_at']??$b['note']['updated_at']??'');return $bt<=>$at;});return $rows;
    }

    private static function teacher_review_detail($teacher_id,array $row) {
        $note=$row['note'];$snapshot=(array)($note['submitted_snapshot']??[]);$review=(array)($note['review']??[]);$history=(array)($note['submission_history']??[]);$can_review=self::can_review($teacher_id,$row['student_id'],$row['class_id']);ob_start(); ?>
        <section id="assignment-review" class="mb-teacher-assignment-detail"><a class="mb-assignment-back" href="<?php echo esc_url(home_url('/teacher-assignments/')); ?>">← Back to Assignment Review</a><header><div><span class="mb-eyebrow"><?php echo esc_html(self::status_label($note['status']??'submitted')); ?> · Version <?php echo absint($snapshot['version']??$note['version']??1); ?></span><h2><?php echo esc_html($snapshot['title']??$note['title']); ?></h2><p><?php echo esc_html($row['student_name']); ?> · <?php echo esc_html($row['class_name']); ?></p></div><?php if(!empty($note['canvas_assignment'])): ?><span class="mb-assignment-source is-canvas">Canvas-linked</span><?php else: ?><span class="mb-assignment-source">MathBinder</span><?php endif; ?></header>
        <div class="mb-assignment-review-layout"><div class="mb-assignment-submission"><h3>Submitted work</h3><?php echo self::attachment_link($snapshot,$row['student_id'],$note['id'],absint($snapshot['version']??0)); ?><?php if(!empty($snapshot['content'])): ?><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($snapshot['content'])); ?></div><?php endif; ?><?php if(!empty($snapshot['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($snapshot['drawing_data']); ?>" alt="Submitted student drawing"><?php endif; ?><?php if(empty($snapshot['content'])&&empty($snapshot['drawing_data'])&&empty($snapshot['attachment']['name'])): ?><p>No viewable work was included in this snapshot.</p><?php endif; ?></div>
        <aside class="mb-assignment-grade-panel"><h3>Grade and feedback</h3><?php if(!$can_review): ?><p>You may view this submission, but your classroom role does not permit grading.</p><?php else: ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="mb_teacher_review_math_note"><input type="hidden" name="student_id" value="<?php echo absint($row['student_id']); ?>"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_teacher_review_math_note','mb_math_note_review_nonce'); ?><label>Decision<select name="decision"><option value="feedback" <?php selected($review['decision']??'','feedback'); ?>>Save feedback</option><option value="revision_requested" <?php selected($review['decision']??'','revision_requested'); ?>>Request revision</option><option value="graded" <?php selected($review['decision']??'','graded'); ?>>Mark graded</option></select></label><label>Grade method<select name="grade_type"><?php foreach(['points'=>'Points','percentage'=>'Percentage','completion'=>'Complete / incomplete','rubric'=>'Rubric'] as $key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($review['grade_type']??'points',$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><div class="mb-assignment-score-row"><label>Score<input type="number" step="0.01" name="score" value="<?php echo esc_attr($review['score']??''); ?>"></label><label>Points possible<input type="number" min="0" step="0.01" name="points_possible" value="<?php echo esc_attr($review['points_possible']??''); ?>"></label></div><label>Rubric level<input maxlength="100" name="rubric_level" value="<?php echo esc_attr($review['rubric_level']??''); ?>"></label><label>Feedback<textarea name="feedback" rows="7" placeholder="Tell the student what was successful and what to revise."><?php echo esc_textarea(wp_strip_all_tags($review['feedback']??'')); ?></textarea></label><button class="mb-teacher-primary" type="submit">Save Review</button></form><?php if(!empty($note['canvas_assignment'])): ?><div class="mb-assignment-canvas-actions"><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="mb_teacher_canvas_note_preview"><input type="hidden" name="student_id" value="<?php echo absint($row['student_id']); ?>"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_teacher_canvas_note_preview','mb_canvas_note_nonce'); ?><button type="submit">Prepare Canvas Preview</button></form><?php echo MathBinder_Canvas_Submission::grade_button($note,$row['student_id']); ?></div><?php endif; ?><?php endif; ?></aside></div>
        <?php if($history): ?><section class="mb-assignment-history"><h3>Submission history</h3><?php foreach(array_reverse($history,true) as $version=>$attempt): $attempt_review=(array)(($note['review_history']??[])[$version]??[]); ?><details <?php echo (string)$version===(string)($snapshot['version']??'')?'open':''; ?>><summary>Attempt <?php echo absint($version); ?> · <?php echo esc_html(!empty($attempt['submitted_at'])?wp_date(get_option('date_format').' '.get_option('time_format'),strtotime($attempt['submitted_at'])):'Submitted'); ?></summary><?php echo self::attachment_link($attempt,$row['student_id'],$note['id'],absint($version)); ?><?php if(!empty($attempt['content'])): ?><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($attempt['content'])); ?></div><?php endif; ?><?php if(!empty($attempt['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($attempt['drawing_data']); ?>" alt="Drawing from attempt <?php echo absint($version); ?>"><?php endif; ?><?php if($attempt_review): ?><p><strong>Teacher decision:</strong> <?php echo esc_html(self::status_label($attempt_review['decision']??'feedback')); ?><?php echo !empty($attempt_review['feedback'])?' — '.esc_html(wp_strip_all_tags($attempt_review['feedback'])):''; ?></p><?php endif; ?></details><?php endforeach; ?></section><?php endif; ?></section>
        <?php return ob_get_clean();
    }

    public static function teacher_review_center($teacher_id,array $classes) {
        $rows=self::teacher_review_rows($teacher_id,$classes);$selected_student=absint($_GET['assignment_student']??0);$selected_id=sanitize_key(wp_unslash($_GET['assignment_work']??''));
        if($selected_student&&$selected_id){foreach($rows as $row)if($row['student_id']===$selected_student&&($row['note']['id']??'')===$selected_id)return self::teacher_review_detail($teacher_id,$row);return '<section id="assignment-review" class="mb-teacher-panel"><div class="mb-teacher-empty"><strong>Submission unavailable.</strong><p>This work is not part of a class available to your account.</p></div></section>';}
        $status=sanitize_key(wp_unslash($_GET['review_status']??'all'));$class_filter=absint($_GET['review_class']??0);$search=sanitize_text_field(wp_unslash($_GET['review_search']??''));
        $counts=['submitted'=>0,'revision_requested'=>0,'feedback'=>0,'graded'=>0];foreach($rows as $row){$key=$row['note']['status']??'submitted';if(isset($counts[$key]))$counts[$key]++;}
        $filtered=array_values(array_filter($rows,function($row)use($status,$class_filter,$search){if($status!=='all'&&($row['note']['status']??'submitted')!==$status)return false;if($class_filter&&$row['class_id']!==$class_filter)return false;if($search!==''&&stripos($row['student_name'].' '.$row['student_email'].' '.($row['note']['title']??''),$search)===false)return false;return true;}));$notice=sanitize_key(wp_unslash($_GET['notes_notice']??''));ob_start(); ?>
        <section id="assignment-review" class="mb-teacher-assignment-center"><header class="mb-assignment-center-hero"><div><span class="mb-eyebrow">Teacher grading workspace</span><h2>Assignment Review</h2><p>Review regular MathBinder and Canvas-linked submissions, preserve every attempt, grade work, or return it for revision.</p></div><strong><?php echo count($rows); ?><small>Total submissions</small></strong></header><?php if($notice): ?><div class="mb-teacher-review-notice <?php echo in_array($notice,['review_denied','canvas_denied','canvas_failed'],true)?'is-error':'is-success'; ?>"><?php echo esc_html(['reviewed'=>'Review saved. The student can now see the grade, feedback, or revision request.','canvas_prepared'=>'Canvas preview prepared; nothing was sent automatically.','review_denied'=>'You do not have permission to grade that submission.','canvas_denied'=>'You do not have permission to prepare that Canvas submission.','canvas_failed'=>'The Canvas preview could not be prepared.'][$notice]??'Assignment review updated.'); ?></div><?php endif; ?><div class="mb-assignment-review-stats"><span><strong><?php echo $counts['submitted']; ?></strong> Waiting</span><span><strong><?php echo $counts['revision_requested']; ?></strong> Revision requested</span><span><strong><?php echo $counts['feedback']; ?></strong> Feedback saved</span><span><strong><?php echo $counts['graded']; ?></strong> Graded</span></div>
        <form class="mb-assignment-review-filters" method="get"><label>Search<input type="search" name="review_search" value="<?php echo esc_attr($search); ?>" placeholder="Student or assignment"></label><label>Class<select name="review_class"><option value="0">All classes</option><?php foreach($classes as $class): ?><option value="<?php echo absint($class['id']); ?>" <?php selected($class_filter,absint($class['id'])); ?>><?php echo esc_html($class['name'].(!empty($class['section_name'])?' · '.$class['section_name']:'')); ?></option><?php endforeach; ?></select></label><label>Status<select name="review_status"><?php foreach(['all'=>'All statuses','submitted'=>'Waiting for review','revision_requested'=>'Revision requested','feedback'=>'Feedback saved','graded'=>'Graded'] as $key=>$label): ?><option value="<?php echo esc_attr($key); ?>" <?php selected($status,$key); ?>><?php echo esc_html($label); ?></option><?php endforeach; ?></select></label><button type="submit">Filter</button></form>
        <?php if(!$filtered): ?><div class="mb-teacher-empty"><strong>No submissions match these filters.</strong><p>New student submissions will appear here automatically.</p></div><?php else: ?><div class="mb-assignment-review-table"><table><thead><tr><th>Status</th><th>Assignment</th><th>Student</th><th>Class</th><th>Version</th><th>Submitted</th><th></th></tr></thead><tbody><?php foreach($filtered as $row): $note=$row['note'];$snapshot=(array)($note['submitted_snapshot']??[]); ?><tr><td><span class="mb-work-status is-<?php echo esc_attr($note['status']??'submitted'); ?>"><?php echo esc_html(self::status_label($note['status']??'submitted')); ?></span></td><td><strong><?php echo esc_html($snapshot['title']??$note['title']); ?></strong><small><?php echo !empty($note['canvas_assignment'])?'Canvas-linked':'MathBinder'; ?></small></td><td><?php echo esc_html($row['student_name']); ?><small><?php echo esc_html($row['student_email']); ?></small></td><td><?php echo esc_html($row['class_name']); ?></td><td>v<?php echo absint($snapshot['version']??$note['version']??1); ?></td><td><?php echo esc_html(!empty($snapshot['submitted_at'])?wp_date(get_option('date_format'),strtotime($snapshot['submitted_at'])):'—'); ?></td><td><a href="<?php echo esc_url(add_query_arg(['assignment_student'=>$row['student_id'],'assignment_work'=>$note['id']],home_url('/teacher-assignments/'))); ?>">Open &amp; Grade</a></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
        <?php return ob_get_clean();
    }

    public static function teacher_section($student_id,array $class_ids) {
        $notes=self::submitted_for_student($student_id,$class_ids); $notice=sanitize_key(wp_unslash($_GET['notes_notice']??'')); $messages=['reviewed'=>'Review and grade saved.','canvas_prepared'=>'Canvas submission preview prepared. Nothing was sent.','canvas_grade_sent'=>'The teacher-approved grade and feedback were sent to Canvas SpeedGrader.','canvas_grade_failed'=>'Canvas did not accept the grade. Review the Canvas mapping and synchronization log.','review_denied'=>'You do not have permission to review that note.','canvas_denied'=>'You do not have permission to prepare that note.','canvas_failed'=>'The Canvas preview could not be prepared.']; ob_start(); ?>
        <?php if($notes): ?><section class="mb-teacher-panel mb-assignment-attempts"><div class="mb-teacher-heading"><div><small>Version history</small><h2>Assignment Files &amp; Attempts</h2><p>Each resubmission remains available as a separate locked version.</p></div></div><?php foreach(array_reverse($notes) as $note): $history=(array)($note['submission_history']??[]); if(!$history)continue; ?><details class="mb-attempt-history"><summary><?php echo esc_html($note['title']); ?> · <?php echo count($history); ?> attempt<?php echo count($history)===1?'':'s'; ?></summary><?php foreach(array_reverse($history,true) as $version=>$attempt): $review=(array)(($note['review_history']??[])[$version]??[]); ?><article><h3>Attempt v<?php echo absint($version); ?></h3><p>Submitted <?php echo esc_html($attempt['submitted_at']??''); ?></p><?php echo self::attachment_link($attempt,$student_id,$note['id'],absint($version)); ?><?php if(!empty($attempt['content'])): ?><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($attempt['content'])); ?></div><?php endif; ?><?php if(!empty($attempt['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($attempt['drawing_data']); ?>" alt="Submitted assignment drawing"><?php endif; ?><?php if($review): ?><p><strong>Review:</strong> <?php echo esc_html(ucwords(str_replace('_',' ',$review['decision']??''))); ?><?php echo !empty($review['feedback'])?' — '.esc_html(wp_strip_all_tags($review['feedback'])):''; ?></p><?php endif; ?></article><?php endforeach; ?></details><?php endforeach; ?></section><?php endif; ?>
        <section id="submitted-math-notes" class="mb-teacher-panel mb-teacher-notes"><div class="mb-teacher-heading"><div><small>Submitted snapshots</small><h2>Math Notes Review</h2><p>Only notes the student deliberately submitted are visible here.</p></div></div><?php if($notice): ?><div class="mb-teacher-review-notice <?php echo in_array($notice,['review_denied','canvas_denied','canvas_failed','canvas_grade_failed'],true)?'is-error':'is-success'; ?>"><?php echo esc_html($messages[$notice]??'Math notes updated.'); ?></div><?php endif; ?><?php if(!$notes): ?><div class="mb-teacher-empty"><strong>No submitted math notes.</strong><p>Private drafts remain private until the student chooses a version to submit.</p></div><?php else: ?><div class="mb-teacher-note-list"><?php foreach(array_reverse($notes) as $note): $s=$note['submitted_snapshot']; $r=(array)($note['review']??[]); ?><article><small><?php echo esc_html(ucwords(str_replace('_',' ',$note['status']))); ?> · Snapshot v<?php echo absint($s['version']); ?></small><h3><?php echo esc_html($s['title']); ?></h3><p><strong><?php echo esc_html(ucfirst($s['organization_type'])); ?>:</strong> <?php echo esc_html($s['organization_label']); ?><?php if(!empty($s['subcategory_label'])): ?> → <strong><?php echo esc_html($s['subcategory_type']?:'Subcategory'); ?>:</strong> <?php echo esc_html($s['subcategory_label']); ?><?php endif; ?></p><div class="mb-note-snapshot"><?php echo wp_kses_post(wpautop($s['content'])); ?></div><?php if(!empty($s['drawing_data'])): ?><img class="mb-note-drawing-preview" src="<?php echo esc_attr($s['drawing_data']); ?>" alt="Submitted math drawing"><?php endif; ?><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>"><input type="hidden" name="action" value="mb_teacher_review_math_note"><input type="hidden" name="student_id" value="<?php echo absint($student_id); ?>"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_teacher_review_math_note','mb_math_note_review_nonce'); ?><div class="mb-grade-grid"><label>Decision<select name="decision"><?php foreach(['feedback'=>'Feedback','revision_requested'=>'Request revision','graded'=>'Grade'] as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($r['decision']??'',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>Grade method<select name="grade_type"><?php foreach(['points'=>'Points','percentage'=>'Percentage','completion'=>'Complete / incomplete','rubric'=>'Rubric'] as $k=>$v): ?><option value="<?php echo esc_attr($k); ?>" <?php selected($r['grade_type']??'',$k); ?>><?php echo esc_html($v); ?></option><?php endforeach; ?></select></label><label>Score<input type="number" step="0.01" name="score" value="<?php echo esc_attr($r['score']??''); ?>"></label><label>Points possible<input type="number" step="0.01" min="0" name="points_possible" value="<?php echo esc_attr($r['points_possible']??''); ?>"></label><label>Rubric level<input maxlength="100" name="rubric_level" value="<?php echo esc_attr($r['rubric_level']??''); ?>"></label></div><label>Feedback<textarea name="feedback" rows="4"><?php echo esc_textarea(wp_strip_all_tags($r['feedback']??'')); ?></textarea></label><button class="mb-teacher-primary" type="submit">Save Review</button></form><form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" onsubmit="return confirm('Prepare this locked snapshot for Canvas preview? Nothing will be sent until you separately approve a grade passback.');"><input type="hidden" name="action" value="mb_teacher_canvas_note_preview"><input type="hidden" name="student_id" value="<?php echo absint($student_id); ?>"><input type="hidden" name="note_id" value="<?php echo esc_attr($note['id']); ?>"><?php wp_nonce_field('mb_teacher_canvas_note_preview','mb_canvas_note_nonce'); ?><button type="submit">Prepare Canvas Preview</button></form><?php echo MathBinder_Canvas_Submission::grade_button($note,$student_id); ?></article><?php endforeach; ?></div><?php endif; ?></section><?php return ob_get_clean();
    }
}
